fn second_largest(v: Vec<Int>) -> Option<Int> {
    let mut largest = 0
    let mut second = 0
    for x in v {
        if x > largest {
            second = largest
            largest = x
        } else if x > second {
            second = x
        }
    }
    if largest > second {
        Some(second)
    } else {
        None
    }
}

